using System;
using System.Collections;
using System.Collections.Generic;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.EventSystems;

public class SmartHomeManager : MonoBehaviour
{
    public GameObject[] products;

    public ProductData[] productDatas;

    [Header("Camera")]
    public Camera camera;

    [Header("Managers")]
    public UIManager uiManager;

    [HideInInspector] public Product selectProduct;

    [HideInInspector] public bool isCalled = false;

    [HideInInspector] public DoorLockEntry[] doorLockEntries;

    [HideInInspector] public ElectricUsageData[] electricUsageData;
    void Start()
    {
        GetProductDataList();
        LoadFromDB();
    }
    private void Update()
    {
        ClickProduct();
    }
    private void GetProductDataList()
    {
        productDatas = new ProductData[products.Length];
        for (int i = 0; i < products.Length; i++)
        {
            productDatas[i] = products[i].GetComponent<Product>().Data;
        }
    }
    
    private void LoadFromDB()
    {
        // TODO: 데이터베이스에서 제품 데이터를 가져오는 로직을 구현해야 합니다.
        // 더미데이터 생성

        List<DoorLockEntry> doorLockList = new List<DoorLockEntry>();

        doorLockList.Add(new DoorLockEntry(3, "2025-07-21", "21:00:00", ""));
        doorLockList.Add(new DoorLockEntry(2, "2025-08-11", "23:00:00", ""));
        doorLockList.Add(new DoorLockEntry(1, "2025-08-19", "08:00:00", ""));

        doorLockEntries = doorLockList.ToArray();

        List<ElectricUsageData> electricUsageDatas = new List<ElectricUsageData>();

        electricUsageDatas.Add(new ElectricUsageData(DateTime.Now, 5.0f));
        electricUsageDatas.Add(new ElectricUsageData(DateTime.Now.AddDays(-5), 15.0f));
        electricUsageDatas.Add(new ElectricUsageData(DateTime.Now.AddDays(-7), 1.0f));

        electricUsageData = electricUsageDatas.ToArray();

        //uiManager.InitDoorLockEntry();
        uiManager.electricUsageChart.ShowUsageChart(DateTime.Now.AddDays(-6), DateTime.Now);
    }

    private void ClickProduct()
    {
        if (Input.GetMouseButtonDown(0) && !EventSystem.current.IsPointerOverGameObject())
        {
            isCalled = false;
            Ray ray = camera.ScreenPointToRay(Input.mousePosition);
            RaycastHit hit;
            if (Physics.Raycast(ray, out hit))
            {
                selectProduct = hit.collider.GetComponent<Product>();
                if (selectProduct)
                {
                    Debug.Log($"선택한 가구 : {selectProduct} | 현재 상태 : {selectProduct.Data.isOn}");
                    uiManager.SetSliderToggleView(true, selectProduct);
                    return;
                }
            }
            uiManager.SetSliderToggleView(false, null);
        }
    }
}
